size_t RegisterJPEGImage(void) {
    MagickInfo *magick_info;
    size_t size = 0;

    /* JPEG Version string and description */
    static char *jpeg_version = "JPEG Library 9.2";
    static char *jpeg_description = "JPEG Image Format";

    /* JPEG format identifiers to create entries for */
    const char *jpeg_identifiers[] = { "JPE", "JPEG", "JPG", "JPS", "PJPEG", NULL };

    for (int i = 0; jpeg_identifiers[i] != NULL; i++) {
        magick_info = SetMagickInfo(jpeg_identifiers[i]);

        if (magick_info != (MagickInfo *) NULL) {
            /* Configure properties for the JPEG format */
            magick_info->decoder = JPEGImage;
            magick_info->encoder = WriteJPEGImage;
            magick_info->thread_support = MagickTrue;

#if defined(JPEG_LIB_VERSION) && (JPEG_LIB_VERSION >= 70)
            magick_info->thread_support = MagickTrue;
#else
            magick_info->thread_support = MagickFalse;
#endif

            magick_info->description = ConstantString(jpeg_description);
            magick_info->version = ConstantString(jpeg_version);
            magick_info->mime_type = ConstantString("image/jpeg");

            /* Register the format */
            magick_info = RegisterMagickInfo(jpeg_identifiers[i], magick_info);
            if (magick_info != (MagickInfo *) NULL)
                size += sizeof(*magick_info);
        }
    }

    return size;
}

